<script setup lang="ts">
import { computed, ref } from 'vue'; import { storeToRefs } from 'pinia'; import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'; import PageHeader from '@/Components/layout/PageHeader.vue'; import SiteForm from '@/Components/sites/SiteForm.vue'; import { useAdministratorStore } from '@/stores/administrator.store'; import { useUiFeedbackStore } from '@/stores/ui-feedback.store'; import type { SiteInput } from '@/types/administrator'
const route = useRoute(); const router = useRouter(); const store = useAdministratorStore(); const feedback = useUiFeedbackStore(); const { users } = storeToRefs(store); const id = computed(() => route.params.siteId as string | undefined); const site = computed(() => id.value ? store.getSiteById(id.value) : undefined); const managers = computed(() => users.value.filter((user) => user.role === 'supervisor' && user.status === 'active')); const dirty = ref(false)
onBeforeRouteLeave(async () => !dirty.value || await feedback.askConfirmation({ title: 'Quitter sans enregistrer ?', message: 'Les modifications de ce site seront perdues.', confirmText: 'Quitter' }))
function submit(payload: SiteInput) { dirty.value = false; const siteId = id.value ? (store.updateSite(id.value, payload), id.value) : store.createSite(payload); feedback.success(id.value ? 'Site mis à jour.' : 'Site enregistré. Vous pourrez compléter sa configuration plus tard.'); void router.push({ name: 'admin-site-details', params: { siteId } }) }
</script>
<template><div class="mx-auto w-full max-w-[1050px]"><PageHeader><template #title>{{ id ? 'Modifier le site' : 'Nouveau site' }}</template><template #description>Définissez le lieu et la zone de présence autorisée.</template><template #actions><v-btn variant="text" prepend-icon="mdi-arrow-left" :to="{ name: 'admin-sites' }">Retour</v-btn></template></PageHeader><v-alert v-if="id && !site" type="error" variant="tonal" title="Site introuvable" /><SiteForm v-else :site="site" :managers="managers" @submit="submit" @cancel="router.back()" @dirty-change="dirty = $event" /></div></template>
